-- --------------------------------------------------------

CREATE TABLE AUX_MUNICIPIOS (
    ID NUMBER PRIMARY KEY,
    SCAD NUMBER(1),
    UF_CODIGO NUMBER,
    CODIGO NUMBER,
    NOME VARCHAR2(250)
);

CREATE SEQUENCE AUX_MUNICIPIOS_SQ
    START WITH 1
    INCREMENT BY 1
    NOMAXVALUE
    NOCACHE
    ORDER;

CREATE OR REPLACE TRIGGER AUX_MUNICIPIOS_TG
    BEFORE INSERT ON AUX_MUNICIPIOS
    FOR EACH ROW
BEGIN
    :NEW.ID := AUX_MUNICIPIOS_SQ.NEXTVAL;
END;
/

